'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict');
const {fixture}=require('./fixture.cjs'),settle=()=>new Promise(r=>setImmediate(r));
function watched(){const facts={observed:[],batches:[]};const f=fixture('train',(doc)=>{const win=doc.defaultView,MO=win.MutationObserver;win.MutationObserver=class extends MO{constructor(callback){super(records=>{facts.batches.push(records);callback(records)})}observe(target,options){facts.observed.push(target);return super.observe(target,options)}}});return{...f,facts};}
test('observe only outermost roots and capture one nested-root mutation once',async()=>{const f=watched();try{for(const target of f.facts.observed)assert(!f.facts.observed.some(other=>other!==target&&other.contains(target)),'nested root unnecessarily observed');const nested=f.target;assert(nested.closest('.sf-panel'));nested.setAttribute('data-unexpected-change','true');await settle();assert.equal(f.facts.batches.flat().length,1);assert.equal(f.invalid()!==null,true);}finally{f.close()}});
test('outside semantic scope is not observed or invalidated',async()=>{const f=watched();try{const node=f.doc.createElement('p');node.textContent='host outside';f.doc.body.prepend(node);node.setAttribute('data-host-change','ok');await settle();assert.equal(f.facts.batches.length,0);assert.equal(f.invalid(),null);assert.equal(f.runtime.refresh(),true);}finally{f.close()}});
test('relocated logical root still rejects without altering external position',()=>{const f=watched();try{const member=f.key(f.profile.panels[0].memberKeys[0]);member.parentElement.append(member);const position=member.previousSibling;assert.throws(()=>f.runtime.refresh(),/semantic|position/);assert.equal(member.previousSibling,position);}finally{f.close()}});
